INSERT INTO `bm_customs_chapters` VALUES (1,1,'1','ສັັດທີ່ມີຊີວິດ','Live animals',NULL,7);
INSERT INTO `bm_customs_chapters` VALUES (2,1,'2','ຊີ້ນ ແລະ ສ່ວນອື່ນໆຂອງສັດທີ່ບໍລິໂພກໄດ້','Meat and edible meat offal',NULL,118);
INSERT INTO `bm_customs_chapters` VALUES (3,1,'3','ປາ ແລະ ສັດນໍ້າຈໍາພວກຄຣັສຕາຊຽນ, ໂມລລັສສ໌ ແລະ​ສັດນໍ້າຈຳພວກທີ່ບໍ່ມີີກະດູກ​ສັນຫຼັງອື່ນໆ','Fish and crustaceans, molluscs and other aquatic invertebrates',NULL,266);
INSERT INTO `bm_customs_chapters` VALUES (4,1,'4','ຜະລິດຕະພັນນົມ; ໄຂ່ສັດປີກ; ນໍ້າເຜິ້ງທຳມະຊາດ;​ ຜະລິດຕະພັນຈາກສັດທີ່ສາມາດບໍລິ​ໂພກໄດ້ທີ່ບໍ່ໄດ້ລະບຸ ຫຼື​ລວມໄວ້ໃນບ່ອນອື່ນ.','Dairy produce; birds’ eggs; natural honey; edible products of animal origin, not elsewhere specified or included',NULL,833);
INSERT INTO `bm_customs_chapters` VALUES (5,1,'5','ຜະລິດຕະພັນຈາກສັດທີ່ບໍ່ໄດ້ລະບຸ ຫຼື​ລວມໄວ້ໃນບ່ອນອື່ນ','Products of animal origin, not elsewhere specified or included',NULL,975);
INSERT INTO `bm_customs_chapters` VALUES (6,2,'6','ຕົ້ົ້ນໄມ້ ແລະ ພືດອື່ນໆທີ່ມີຊີວິດ; ຫົວ, ຮາກ ແລະ ສິ່ງທີ່ຄ້າຍຄືກັນ; ດອກໄມ້ ແລະ​ໃບ​ໄມ້ທີ່​ໃຊ້​ໃນ​ການ​ຕົບແຕ່ງ','Live trees and other plants; bulbs, roots and the like; cut flowers and ornamental foliage',NULL,1041);
INSERT INTO `bm_customs_chapters` VALUES (7,2,'7','ພືດຜັກລວມທັງ​ຮາກ ແລະ ຫົວບາງຊະນິດທີ່ບໍລິໂພກໄດ້','Edible vegetables and certain roots and tubers',NULL,1105);
INSERT INTO `bm_customs_chapters` VALUES (8,2,'8','ໝາກໄມ້ ແລະ​ຖົ່ວເປືອກແຂງທີ່ບໍລິໂພກໄດ້; ເປືອກໝາກໄມ້ຈໍາພວກໝາກກ້ຽງ ຫຼື​ ໝາກແຕງເມລ່ອນ','Edible fruit and nuts; peel of citrus fruit or melons',NULL,1337);
INSERT INTO `bm_customs_chapters` VALUES (9,2,'9','ກາເຟ, ຊາ, ຊາມາເຕ ແລະ ເຄື່ອງເທດ​','Coffee, tea, maté and spices',NULL,1525);
INSERT INTO `bm_customs_chapters` VALUES (10,2,'10','ທັນຍາພືດ','Cereals',NULL,1682);
INSERT INTO `bm_customs_chapters` VALUES (11,2,'11','ຜະລິດຕະພັນຂອງອຸດສະຫະກຳໂຮງສີເມັດທັນຍາພືດ; ເຂົ້າມອລທ໌; ສຕາຣຈ໌; ອິນູລິນ; ​ກລູເທນຈາກສາລີ','Products of the milling industry; malt; starches; inulin; wheat gluten',NULL,1762);
INSERT INTO `bm_customs_chapters` VALUES (12,2,'12','ເມັດພືດ ແລະ ໝາກໄມ້ທີ່ມີນໍ້າມັນ; ເມັດທັນຍາພືດ, ເມັດພືດ ແລະ ໝາກໄມ້ຕ່າງໆ; ພືດທີ່ໃຊ້ໃນອຸດສະຫະກຳ ຫຼື ໃຊ້ເປັນຢາ, ເຟືອງ ແລະ ຫຍ້າທີ່ໃຊ້ເປັນອາຫານສັດ.','Oil seeds and oleaginous fruits; miscellaneous grains, seeds and fruit; industrial or medicinal plants; straw and fodder',NULL,1867);
INSERT INTO `bm_customs_chapters` VALUES (13,2,'13','ຂີ້ຄັ່ງ; ຢາງໄມ້, ນໍ້າມັນຢາງໄມ້ ແລະ ນໍ້າຫຼໍ່ລ້ຽງ ແລະ ສິ່ງສະກັດອື່ນໆ ຈາກພືດ','Lac; gums, resins and other vegetable saps and extracts',NULL,2048);
INSERT INTO `bm_customs_chapters` VALUES (14,2,'14','ວັດຖຸຈາກພືດທີ່ໃຊ້; ຜະລິດຕະພັນຈາກພືດທີ່ບໍ່ໄດ້ລະບຸ ຫຼື ລວມໄວ້ຢູ່ບ່ອນອື່ນ','Vegetable plaiting materials;  vegetable products not elsewhere specified or included',NULL,2120);
INSERT INTO `bm_customs_chapters` VALUES (15,3,'15','ໄຂມັນ ແລະ ນໍ້າມັນທີ່ໄດ້ຈາກສັດ ຫຼື ພືດ ແລະ ຜະລິດຕະພັນທີ່ແຍກໄດ້ຈາກໄຂມັນ ແລະ ນໍ້າມັນດັ່ງກ່າວ; ໄຂມັນທີ່ບໍລິໂພກໄດ້ ຊຶ່ງຜ່ານການປຸງແຕ່ງແລ້ວ; ໄຂມັນທີ່ໄດ້ມາຈາກສັດ ຫຼື ພືດ','Animal or vegetable fats and oils and their cleavage products; prepared edible fats; animal or vegetable waxes',NULL,2158);
INSERT INTO `bm_customs_chapters` VALUES (16,4,'16','ສິ່ງປຸງແຕ່ງຈາກຊີ້ນສັດ, ປາ ຫຼື ສັດນໍ້າປະເພດຄຣັສຕາຊຽນ, ໂມລັສສ໌ ຫຼື ສັດນໍ້າອື່ນໆ ທີ່ບໍ່ມີກະດູກສັນຫຼັງ','Preparations of meat, of fish or of crustaceans, molluscs or other aquatic invertebrates',NULL,2490);
INSERT INTO `bm_customs_chapters` VALUES (17,4,'17','ນໍ້າຕານ ແລະ ເຂົ້າໜົມທີ່ເຮັດຈາກນໍ້າຕານ','Sugars and sugar confectionery',NULL,2631);
INSERT INTO `bm_customs_chapters` VALUES (18,4,'18','ໂກໂກ້ ແລະ ສິ່ງປຸງແຕ່ງທີ່ເຮັດຈາກໂກໂກ້','Cocoa and cocoa preparations',NULL,2701);
INSERT INTO `bm_customs_chapters` VALUES (19,4,'19','ສິ່ງປຸງແຕ່ງຈາກທັນຍະພືດ, ແປ້ງ, ແປ້ງສະຕາດຈ໌ ຫຼື ນົມ; ຜະລິດຕະພັນອາຫານຈາກແປ້ງເພສທຣີ','Preparations of cereals, flour, starch or milk; pastrycooks\' products',NULL,2735);
INSERT INTO `bm_customs_chapters` VALUES (20,4,'20','ສິ່ງປຸງແຕ່ງຈາກພືດຜັກ, ໝາກໄມ້, ຖົ່ວເປືອກແຂງ ຫຼື ຈາກສ່ວນອື່ນໆ ຂອງພືດ.','Preparations of vegetables, fruit, nuts or other parts of plants',NULL,2876);
INSERT INTO `bm_customs_chapters` VALUES (21,4,'21','ສິ່ງປຸງແຕ່ງອື່ນໆ ທີ່ບໍລິໂພກໄດ້.','Miscellaneous edible preparations',NULL,3044);
INSERT INTO `bm_customs_chapters` VALUES (22,4,'22','ເຄື່ອງດື່ມ, ເຫຼົ້າ ແລະ ນໍ້າສົ້ມສາຍຊູ','Beverages,  spirits and vinegar',NULL,3181);
INSERT INTO `bm_customs_chapters` VALUES (23,4,'23','ກາກ ແລະ ສິ່ງເສດເຫຼືອຈາກອຸດສະຫະກໍາຜະລິດອາຫານ; ສິ່ງປຸງແຕ່ງສຳລັບໃຊ້ເປັນອາຫານສັດ','Residues and waste from the food industries; prepared animal fodder',NULL,3357);
INSERT INTO `bm_customs_chapters` VALUES (24,4,'24','ຢາສູບ ແລະ ຜະລິດຕະພັນທີ່ໃຊ້ແທນຢາສູບ','Tobacco and manufactured tobacco substitutes',NULL,3467);
INSERT INTO `bm_customs_chapters` VALUES (25,5,'25','ເກືອ,ມາດ, ດິນ ແລະ ຫິນ; ວັດຖຸຈຳພວກພລາສເຕີຣ໌, ປູນຂາວ ແລະ ຊິເມນທ໌','Salt; sulphur; earths and stone; plastering materials, lime and cement',NULL,3545);
INSERT INTO `bm_customs_chapters` VALUES (26,5,'26','ແຮ່, ຂີ້ໂລຫະ ແລະ ຂີ້ເຖົ່າ','Ores, slag and ash',NULL,3731);
INSERT INTO `bm_customs_chapters` VALUES (27,5,'27','ເຊື້ອໄຟທີ່ໄດ້ຈາກແຮ່, ນໍ້າມັນແຮ່ ແລະ ຜະລິດຕະພັນທີ່ໄດ້ຈາກການກັ່ນຕອງຂອງສິ່ງດັ່ງກ່າວ; ສານບີທູມີນັສໃຊ້ສຳລັບປູທາງ; ໄຂທີ່ໄດ້ຈາກແຮ່','Mineral fuels, mineral oils and products of their distillation; bituminous substances; mineral waxes',NULL,3838);
INSERT INTO `bm_customs_chapters` VALUES (28,6,'28','ເຄມີອະນິນຊີ; ສານປະກອບອິນຊີ ຫຼື ສານປະກອບອະນິນຊີຂອງໂລຫະທີ່ມີຄ່າ, ຂອງໂລຫະຈໍາພວກແຣຣ໌-​​ເອີດທ໌ຂອງທາດກຳມັນຕະພາບລັງສີ ແລະ ຂອງໄອໂຊໂທບ','Inorganic chemicals; organic or inorganic compounds of precious metals, of rare-earth metals, of radioactive elements or of isotopes',NULL,4042);
INSERT INTO `bm_customs_chapters` VALUES (29,6,'SUB-CHAPTER II','','INORGANIC ACIDS AND INORGANIC OXYGEN COMPOUNDS of NON-METALS',NULL,4126);
INSERT INTO `bm_customs_chapters` VALUES (30,6,'SUB-CHAPTER III','','HALOGEN OR SULPHUR COMPOUNDS of NON-METAL',NULL,4172);
INSERT INTO `bm_customs_chapters` VALUES (31,6,'SUB-CHAPTER IV','','INORGANIC BASES AND OXIDES, HYDROXIDES AND PEROXIDES of METALS',NULL,4190);
INSERT INTO `bm_customs_chapters` VALUES (32,6,'SUB-CHAPTER V','','SALTS AND PEROXYSALTS of INORGANIC ACIDS AND METALS',NULL,4251);
INSERT INTO `bm_customs_chapters` VALUES (33,6,'SUB-CHAPTER VI','','MISCELLANEOUS',NULL,4420);
INSERT INTO `bm_customs_chapters` VALUES (34,6,'29','ເຄມີທີ່ມີອິນຊີ','Organic chemicals',NULL,4500);
INSERT INTO `bm_customs_chapters` VALUES (35,6,'SUB-CHAPTER II','','HYDROCARBONS AND THEIR HALOGENATED, SULPHONATED, NITRATED OR NITROSATED DERIVATIVES',NULL,4550);
INSERT INTO `bm_customs_chapters` VALUES (36,6,'SUB-CHAPTER II','','ALCOHOLS AND THEIR HALOGENATED, SULPHONATED, NITRATED OR NITROSATED DERIVATIVES',NULL,4649);
INSERT INTO `bm_customs_chapters` VALUES (37,6,'SUB-CHAPTER III','','PHENOLS, PHENOL-ALCOHOLS, AND THEIR HALOGENATED, SULPHONATED, NITRATED OR NITROSATED DERIVATIVES',NULL,4693);
INSERT INTO `bm_customs_chapters` VALUES (38,6,'SUB-CHAPTER IV','','ETHERS, ALCOHOL PEROXIDES, ETHER PEROXIDES, KETONE PEROXIDES, EPOXIDES WITH A THREE-MEMBERED RING, ACETALS AND HEMIACETALS, AND THEIR HALOGENATED, SULPHONATED, NITRATED OR NITROSATED DERIVATIVES',NULL,4720);
INSERT INTO `bm_customs_chapters` VALUES (39,6,'SUB-CHAPTER V','','ALDEHYDE-FUNCTION COMPOUNDS',NULL,4749);
INSERT INTO `bm_customs_chapters` VALUES (40,6,'SUB-CHAPTER VI','','KETONE-FUNCTION COMPOUNDS AND QUINONE-FUNCTION COMPOUNDS',NULL,4775);
INSERT INTO `bm_customs_chapters` VALUES (41,6,'SUB-CHAPTER VII','','CARBOXYLIC ACIDS AND THEIR ANHYDRIDES, HALIDES, PEROXIDES AND PEROXYACIDS AND THEIR HALOGENATED, SULPHONATED, NITRATED OR NITROSATED DERIVATIVES',NULL,4805);
INSERT INTO `bm_customs_chapters` VALUES (42,6,'SUB-CHAPTER VIII','','ESTERS of INORGANIC ACIDS of NON-METALS AND THEIR SALTS, AND THEIR HALOGENATED, SULPHONATED, NITRATED OR NITROSATED DERIVATIVES',NULL,4918);
INSERT INTO `bm_customs_chapters` VALUES (43,6,'SUB-CHAPTER IX','','NITROGEN-FUNCTION COMPOUNDS',NULL,4938);
INSERT INTO `bm_customs_chapters` VALUES (44,6,'SUB-CHAPTER X','','ORGANO-INORGANIC COMPOUNDS, HETEROCYCLIC COMPOUNDS, NUCLEIC ACIDS AND THEIR SALTS, AND SULPHONAMIDES',NULL,5071);
INSERT INTO `bm_customs_chapters` VALUES (45,6,'SUB-CHAPTER XI','','PROVITAMINS, VITAMINS AND HORMONES',NULL,5203);
INSERT INTO `bm_customs_chapters` VALUES (46,6,'SUB-CHAPTER XII','','GLYCOSIDES AND ALKALOIDS, NATURAL OR REPRODUCED BY SYNTHESIS, AND THEIR SALTS, ETHERS, ESTERS AND OTHER DERIVATIVES',NULL,5235);
INSERT INTO `bm_customs_chapters` VALUES (47,6,'SUB-CHAPTER XII','','OTHER ORGANIC COMPOUNDS',NULL,5277);
INSERT INTO `bm_customs_chapters` VALUES (48,6,'30','ຜະ​ລິດ​ຕະ​ພັນ​ການຢາ','Pharmaceutical products',NULL,5315);
INSERT INTO `bm_customs_chapters` VALUES (49,6,'31','ປຸ໋ຍ','Fertilisers',NULL,5558);
INSERT INTO `bm_customs_chapters` VALUES (50,6,'32','ສິ່ງ​ສະ​ກັດ​ທີ່​ໃຊ້​ຟອກ​ ຫຼື ​ຍ້ອມ​ສີ; ແທນ​ນິນ ແລະ ​ອະນຸ​ພັນ​ຂອງສິ່ງດັ່ງກ່າວ; ສີ​ຍ້ອມ​, ສານ​ສີ ພິກເມນ​ທ໌ ແລະ​ ສານສີ​ອື່ນໆ; ສີ​ທາ ແລະ​ ສີວາ​ນິສ; ກາວພັດ​ຕີ້ ແລະ​ ກາວມາ​ສ​ຕີກ​ອື່ນໆ; ນໍ້າມຶກ','Tanning or dyeing extracts; tannins and their derivatives; dyes, pigments and other colouring matter; paints and varnishes;  putty and other mastics; inks',NULL,5654);
INSERT INTO `bm_customs_chapters` VALUES (51,6,'33','ນໍ້າ​ມັນຍອດ​ຫົວ ແລະ ຢາງ​ໄມ້; ນໍ້າ​ຫອມ, ເຄື່ອງສຳອາງ ຫຼື ເຄື່ອງເສີມສວຍ.','Essential oils and resinoids; perfumery, cosmetic or toilet preparations',NULL,5855);
INSERT INTO `bm_customs_chapters` VALUES (52,6,'34','ສະ​ບູ, ສານ​ອິນຊີ​ສຳ​ລັບ​ລົດ​ຄວາມ​ເຄັ່ງ​ຂອງ​ຜິວ, ສິ່ງ​ປຸງ​ແຕ່ງ​ທີ່​ໃຊ້​ສຳ​ລັບ​ຊັກ​ລ້າງສິ່ງປຸງ​ແຕ່ງ​ທີ່​ໃຊ້ຫຼໍ່​ລື່ນ, ໄຂ​ທຽມ, ໄຂ​​ປຸ​ງ​ແຕ່ງ, ສິ່ງ​ປຸງ​ແຕ່ງ​ທີ່​ໃຊ້​ຂັດ​ເງົາ ແລະ ຖູ, ທຽນ​ໄຂ ແລ​ະ ສິ່ງ​ທີ່ຄ້າຍ​ຄື​ກັນ, ແປ້ງ​ໜຽວໃຊ້​ສຳ​ລັບ​ປັ້ນ​ແບບ, \"ໄຂທີ່ໃຊ້ທາງ ທັນຕະກຳ\" ແລະ ສິ່ງ​ປຸງ​ແຕ່ງ​ທາງ​ທັນ​ຕະ​ກຳ ຊຶ່ງມີພລາສເຕີຣ໌​ເປັນ​ຫຼັກ','Soap, organic surface-active agents, washing preparations, lubricating preparations, artificial waxes, prepared waxes, polishing or scouringpreparations, candles and similar articles, modelling \npastes, “dental waxes” and dental preparations with a basis of plaster',NULL,5958);
INSERT INTO `bm_customs_chapters` VALUES (53,6,'35','ສານ​ແອ​ລ​ບູ​ມີ​ນອຍ​ດ໌; ໂມ​ດີ​ໄຟ​ດ໌​ສ​ຕາ​ຣ໌; ກາວ; ເອນ​ໄຊ​ມ໌','Albuminoidal substances; modified starches; glues; enzymes',NULL,6119);
INSERT INTO `bm_customs_chapters` VALUES (54,6,'36','ວັດ​ຖຸ​ລະ​ເບີດຜະ​ລິດ​ຕະ​ພັນ​ດອກ​ໄມ້​ໄຟ, ໄມ້​ຂີດ​ໄຟ, ແອ​ລ​ລອຍ​ທີ່​ເຮັດ​ໃຫ້ເກີດ​ປະ​ກາຍ​ໄຟ, ສິ່ງປຸງແຕ່ງທີ່ໄວໄຟໄດ້ບາງຊະນິດ.','Explosives; pyrotechnic products; matches; pyrophoric alloys; certain combustible preparations',NULL,6190);
INSERT INTO `bm_customs_chapters` VALUES (55,6,'37','ຜະ​ລິດ​ຕະ​ພັນ​ທີ່​ໃຊ້​ໃນ​ການ​ຖ່າຍ​ຮູບ ຫຼື ​ຖ່າຍທຳຮູບ​ເງົາ.','Photographic or cinematographic goods',NULL,6265);
INSERT INTO `bm_customs_chapters` VALUES (56,6,'38','ຜະ​ລິດ​ຕະ​ພັນ​​ເຄ​ມີປະສົມສຳເລັດຮູບ.','Miscellaneous chemical products',NULL,6373);
INSERT INTO `bm_customs_chapters` VALUES (57,7,'39','ພ​ລາ​ສ​ຕິກ ແລະ​ ເຄື່ອງໃຊ້​ທີ່​ເຮັດ​ດ້ວຍ​ພ​ລາ​ສ​ຕິກ','Plastics and articles thereof',NULL,6696);
INSERT INTO `bm_customs_chapters` VALUES (58,7,'SUB-CHAPTER II','','WASTE, PARINGS AND SCRAP; SEMI-MANUFACTURES; ARTICLES',NULL,6997);
INSERT INTO `bm_customs_chapters` VALUES (59,7,'40','ຢາງ ແລະ ເຄື່ອງໃຊ້ທີ່​ເຮັດ​ດ້ວຍ​ຢາງ','Rubber and articles thereof',NULL,7384);
INSERT INTO `bm_customs_chapters` VALUES (60,8,'41','ໜັງດິບ (ນອກ​ຈາ​ກ​ໜັງ​ຂົນ​ສັດ) ແລະ ​ໜັງ​ຟອກ','Raw hides and skins (other than furskins) and leather',NULL,7793);
INSERT INTO `bm_customs_chapters` VALUES (61,8,'42','ເຄື່ອງ​​ໜັງ, ​ເຄື່ອງອານ ແລະ ​ເຄື່ອງ​ທຽມລາກ; ເຄື່ອງໃຊ້ສຳລັບການເດີນທາງ, ກະເປົາຫີ້ວ ແລະ ​ພາ​ຊະ​ນະບັນຈຸທີ່​ຄ້າຍ​ຄື​ກັນ; ເຄື່ອງຂອງທີ່ເຮັດດ້ວຍໃສ້ສັດ (ນອກຈາກໃສໂຕໄໝ)','Articles of leather; saddlery and harness; travel goods, handbags and similar containers; articles of animal gut \n(other than silk-worm gut)',NULL,7883);
INSERT INTO `bm_customs_chapters` VALUES (62,8,'43','ໜັງ​ຂົນ​ສັດ ແລະ ຂົນ​ທຽມ; ​ຜະ​ລິດ​ຕະ​ພັນ​ຂອງສິ່ງ​ດັ່ງ​ກ່າວ','Furskins and artificial fur; manufactures thereof',NULL,7980);
INSERT INTO `bm_customs_chapters` VALUES (63,9,'44','ໄມ້ ແລະ ​ເຄື່ອງໃຊ້ທີ່​ເຮັດ​ດ້ວຍ​ໄມ້; ຖ່ານ​ໄມ້.','Wood and articles of wood; wood charcoal',NULL,8057);
INSERT INTO `bm_customs_chapters` VALUES (64,9,'45','ໄມ້ກ໊ອກ ແລະ​ ເຄື່ອງ​ທີ່​ເຮັດ​ດ້ວຍ​ໄມ້ກ໊ອກ','Cork and articles of cork',NULL,8456);
INSERT INTO `bm_customs_chapters` VALUES (65,9,'46','ຜະ​ລິດ​ຕະ​ພັນ​ທີ່​ເຮັດ​ດ້ວຍ​ເຟືອງ, ເຮັດ​ດ້ວຍ​ເອ​ສ​ພາຣ໌ໂຕ ຫຼື​ ວັດ​ຖຸ​ຈັກ​ສານ​ອື່ນໆ; ສິ່ງຈັກ​ສານ ແລະ ຜະລິດຕະພັນເຄື່ອງ​ສານ​ອື່ນໆ.','Manufactures of straw, of esparto or of other plaiting materials; basketware and wickerwork',NULL,8494);
INSERT INTO `bm_customs_chapters` VALUES (66,10,'47','ເຍື່ອໄມ້ທີ່ໄດ້ຈາກໄມ້ ຫຼື ໄດ້ຈາກວັດຖຸຈຳພວກເສັ້ນໄຍເຊລູໂລສອື່ນໆ; ເຈ້ຍ ຫຼື ເຈ້ຍແຂງທີ່ນຳກັບມາໃຊ້ຄືນອີກ ( ເສດ ແລະສິ່ງທີ່ໃຊ້ບໍ່ໄດ້)','Pulp of wood or of other fibrous cellulosic material; recovered (waste and scrap) paper or paperboard',NULL,8566);
INSERT INTO `bm_customs_chapters` VALUES (67,10,'48','ເຈ້ຍ ແລະ ​ເຈ້ຍ​ແຂງ; ເຄື່ອງ​ໃຊ້​ທີ່​ເຮັດ​ດ້ວຍ​ເຍື້ອ​ຂອງ​ເຈ້ຍ, ເຮັດດ້ວຍເຈ້ຍ ຫຼື​ ເຈ້ຍ​ແຂງ','Paper and paperboard; articles of paper pulp, of paper or of paperboard',NULL,8640);
INSERT INTO `bm_customs_chapters` VALUES (68,10,'49','ປື້ມຕໍາລາ, ໜັງ​ສື​ພິມ, ຮູບ​ພາບ ແລະ​ ຜະ​ລິດ​ຕະ​ພັນ​ອື່ນໆ ຂອງ​ອຸດ​ສະ​ຫະ​ກຳ​ການ​ພິມ; ຕົ້ົ້ນ​ສະ​ບັບ​ທີ່​ຂຽນດ້ວຍມື, ​ພິມ​ດີດ ແລ​ະ​ ແຜນ​ວາດ.','Printed books, newspapers, pictures and other products of the printing industry; manuscripts, typescripts and plans',NULL,9142);
INSERT INTO `bm_customs_chapters` VALUES (69,11,'50','ໄໝ','Silk',NULL,9389);
INSERT INTO `bm_customs_chapters` VALUES (70,11,'51','ຂົນ​ແກະ, ຂົນ​ລະ​ອຽດ ຫຼື ​ຂົນ​ຫຍາບ​ຂອງ​ສັດ; ດ້າຍຂົນມ້າ ແລະ​ ແຜ່ນ​ແພທີ່​ເຮັດ​ຈາກ​ຂົນ​ຂອງ​ສັດ','Wool, fine or coarse animal hair; horsehair yarn and woven fabric',NULL,9421);
INSERT INTO `bm_customs_chapters` VALUES (71,11,'52','ຝ້າຍ','Cotton',NULL,9542);
INSERT INTO `bm_customs_chapters` VALUES (72,11,'53','ເສັ້ນ​ໄຍຕ່ຳທີ່​ໄດ້​ຈາ​ກພືດອື່ນໆ; ເສັ້ນ​ດ້າຍ​ເຈ້ຍ ແລະ​ ແຜ່ນ​ແພ​ຈາກ​ດ້າຍ​ເຈ້ຍ','Other vegetable textile fibres; paper yarn and woven fabrics of paper yarn',NULL,9800);
INSERT INTO `bm_customs_chapters` VALUES (73,11,'54','ເສັ້ນ​ໄຍ​ຍາວສັງເຄາະ; ແຖບ ແລະ ເສັ້ນໄຍທີ່ຄ້າຍຄືກັນ ທີ່ເຮັດດ້ວຍວັດຖຸແຜ່ນແພປະດິດ','Man-made filaments; strip and the like of man-made textile materials',NULL,9878);
INSERT INTO `bm_customs_chapters` VALUES (74,11,'55','ເສັ້ນ​ໄຍ​ສັ້ນ​ສ້ງເຄາະ','Man-made staple fibres',NULL,10033);
INSERT INTO `bm_customs_chapters` VALUES (75,11,'56','ນູ່ນ, ສັກ​ກະ​ຫຼາດ ແລະ​ ແຜ່ນ​ແພ​ທີ່​ບໍ່​ໄດ້​ຕ່ຳ; ເສັ້ນ​ດ້າຍ​ພິ​ເສດ; ເຊືອກຝັ້ນ (ຊະນິດທໄວນ), ເຊືອກທຳມະດາ (ຊະ​ນິດ​ຄອ​ຣ໌ເດ​ດຈ໌), ເຊືອກຖັກ (ຊະ​ນິດ​ໂຣບ) ແລະ​ເຊືອກເສັ້ນໃຫຍ່ (ຊະນິດເຄເບິລ) ແລະ ​ເຄື່ອງ​ຂອງ​ທີ່ເຮັດ​ດ້ວຍ​ວັດຖຸດັ່ງ​ກ່າວ.','Wadding, felt and nonwovens; special yarns; twine, cordage, ropes and cables and articles thereof',NULL,10238);
INSERT INTO `bm_customs_chapters` VALUES (76,11,'57','ຜ້າ​ພົມ ແລະ ​ສິ່ງປູ​ພື້ນ​ອື່ນໆທີ່​ເຮັດ​ດ້ວຍ​ວັດ​ຖຸ​ຕ່ຳ​ແຜ່ນ','Carpets and other textile floor coverings',NULL,10334);
INSERT INTO `bm_customs_chapters` VALUES (77,11,'58','ຜ້າ​ຕໍ່າຊະ​ນິດພິ​ເສດ; ​ຜ້າມີຂົນແບບທັຟທ໌; ຜ້າ​ລູກ​ໄມ້; ຜ້າໃຊ້ປະດັບ; ຜ້າ​ທີ່​ໃຊ້​ຕົບ​ແຕ່ງຂອບ; ຜ້າ​ປັກ​ແສ່ວ','Special woven fabrics; tufted textile fabrics; lace; tapestries; trimmings; embroidery',NULL,10588);
INSERT INTO `bm_customs_chapters` VALUES (78,11,'59','ຜ້າ​ຕ່ຳ​ທີ່​ອາບຊຶມ, ເຄືອບ, ຫຸ້ມ ຫຼື​ ອັດ​ເປັນ​ຊັ້ນເຄື່ອງ​ທີ່​ເຮັດ​ດ້ວຍ​ວັດ​ຖຸແຜ່ນ; ​ແພ​ຕໍ່າຊະນິດທີ່​ເໝາະ​ສໍາລັບ​ໃຊ້​ໃນ​ອຸດ​ສະຫະ​ກໍາ','Impregnated, coated, covered or laminated textile fabrics; textile articles of a kind suitable for industrial use',NULL,10774);
INSERT INTO `bm_customs_chapters` VALUES (79,11,'60','ຜ້າ​ຖັກ​ແບບ​ນິດ ແລະ​ ແບບ​ໂຄ​ຣ​ເຊັດ​ທ໌','Knitted or crocheted fabrics',NULL,10929);
INSERT INTO `bm_customs_chapters` VALUES (80,11,'61','ເຄື່ອງ​ນຸ່ງ​ຫົ່ມ ແລະ ​ເຄື່ອງ​ປະ​ກອບ​ໃຊ້​ກັບ​ເຄື່ອງ​ນຸ່ງ​ຫົ່ມ, ທີ່​ເຮັດ​ດ້ວຍ​ຜ້າ​ທີ່ຖັກແບບ​ນິດ ຫຼື ​ແບບ​ໂຄ​ຣ​ເຊັດ​ທ໌','Articles of apparel and clothing accessories, knitted or crocheted',NULL,11084);
INSERT INTO `bm_customs_chapters` VALUES (81,11,'62','ເຄື່ອງນຸ່ງ​ຫົ່ມ ແລະ​ ເຄື່ອງປະ​ກອບທີ່ໃຊ້ກັບເຄື່ອງ​ນຸ່ງ​ຫົ່ມ, ທີ່​ບໍ່​ເຮັດດ້ວຍຜ້າຖັກແບບ​ນິດທ໌ ຫຼື ​ແບບ​ໂຄ​ຣ​ເຊັດ​ທ໌','Articles of apparel and clothing accessories, not knitted or crocheted',NULL,11364);
INSERT INTO `bm_customs_chapters` VALUES (82,11,'63','ເຄື່ອງ​ຂອງທີ່​ເຮັດ​ດ້ວຍ​ວັດ​ຖຸ​ຕ່ຳ​ແຜ່ນ​ອື່ນໆ; ເຄື່ອງ​ຈັດເປັນ​ຊຸດ; ເຄື່ອງ​ນຸ່ງ​ຫົ່ມ​ ແລະ ເຄື່ອງທີ່ເຮັດດ້ວຍວັດຖຸຕ່ຳແຜ່ນທີ່​ໃຊ້​ແລ້ວ; ຜ້າ​ເສດ','Other made up textile articles; sets; worn clothing and worn textile articles; rags',NULL,11792);
INSERT INTO `bm_customs_chapters` VALUES (83,11,'SUB-CHAPTER I','','OTHER MADE UP TEXTILE ARTICLES',NULL,11814);
INSERT INTO `bm_customs_chapters` VALUES (84,11,'SUB-CHAPTER II','','SETS',NULL,11961);
INSERT INTO `bm_customs_chapters` VALUES (85,11,'SUB-CHAPTER III','','WORN CLOTHING AND WORN TEXTILE ARTICLES; RAGS',NULL,11965);
INSERT INTO `bm_customs_chapters` VALUES (86,12,'64','ເກີບ, ສະ​ນັບແຂ່ງ ແລະ​ ເຄື່ອງ​​ທີ່​ຄ້າຍ​ຄຽງ; ສິ້ນສ່ວນຂອງເຄື່ອງດັ່ງ​ກ່າວ','Footwear, gaiters and the like; parts of such articles',NULL,12003);
INSERT INTO `bm_customs_chapters` VALUES (87,12,'65','ເຄື່ອງ​ສຸບ​ຫົວ ແລະ ສິ້ນ​ສ່ວນຂອງເຄື່ອງດັ່ງ​ກ່າວ','Headgear and parts thereof',NULL,12149);
INSERT INTO `bm_customs_chapters` VALUES (88,12,'66','ຄັນ​ຮົ່ມ, ຄັນຮົ່ມກັນແດດ, ໄມ້​ຄ້ອນເທົ້ົ້າ, ໄມ້​ຄ້ອນເທົ້ົ້າ​ທີ່​ເປັນຕັ່ງ​ນັ່ງ, ໄມ້ແສ້, ໄມ້ແສ້ສຳລັບຂີ່ມ້າ ແລະ ສິ້ນ​ສ່ວນຂອງສິ່ງດັ່ງ​ກ່າວ','Umbrellas, sun umbrellas, walking-sticks, seat-sticks, whips, riding-crops, and parts thereof',NULL,12186);
INSERT INTO `bm_customs_chapters` VALUES (89,12,'67','ຂົນ​ແຂງ  ແລະ​ ຂົນອ່ອນຂອງສັດ​ປີກ​ທີ່​ຕົບແຕ່ງແລ້ວ ແລະ​ ເຄື່ອງ​ຂອງທີ່ເຮັດ​ດ້ວຍຂົນ​ດັ່ງ​ກ່າວ; ດອກ​ໄມ້​ທຽມ; ເຄື່ອງ​ຂອງທີ່ເຮັດ​ດ້ວຍ​ຜົມຄົນ','Prepared feathers and down and articles made of feathers or of down; artificial flowers; articles of human hair',NULL,12222);
INSERT INTO `bm_customs_chapters` VALUES (90,13,'68','ເຄື່ອງ​ທີ່​ເຮັດ​ດ້ວຍ​ຫິນ, ພ​ລາ​ສ​ເຕີ​ຣ໌, ຊີ​ເມັນ, ດິນຈີ່ທົນໄຟ (ແອ​ສ​ເບ​ສ​ທອ​ສ), ຫິນຊະນິດໄມ​ກາ ຫຼື ​ວັດ​ຖຸ​ທີ່ຄ້າຍ​ຄຽງກັນ','Articles of stone, plaster, cement, asbestos, mica or similar materials',NULL,12298);
INSERT INTO `bm_customs_chapters` VALUES (91,13,'69','ຜະ​ລິດ​ຕະ​ພັນດິນເຜົາ','Ceramic products',NULL,12505);
INSERT INTO `bm_customs_chapters` VALUES (92,13,'SUB-CHAPTER I','','GOODS of SILICEOUS FOSSIL MEALS OR of SIMILAR SILICEOUS EARTHS, AND REFRACTORY GOODS',NULL,12525);
INSERT INTO `bm_customs_chapters` VALUES (93,13,'SUB-CHAPTER II','','OTHER CERAMIC PRODUCTS',NULL,12542);
INSERT INTO `bm_customs_chapters` VALUES (94,13,'70','ແກ້ວ ແລະ​ ເຄື່ອງໃຊ້ທີ່ເຮັດ​ດ້ວຍ​ແກ້ວ','Glass and glassware',NULL,12651);
INSERT INTO `bm_customs_chapters` VALUES (95,14,'71','ໄຂ່​ມຸກ​ທຳ​ມະ​ຊາດ ຫຼື​ ໄຂ່​ມຸກ​ລ້ຽງ, ແກ້ວ​ປະ​ເສີດ ຫຼື ແກ້ວທີ່ຄ້າຍຄືກັນ, ໂລ​ຫະ​ມີຄ່າ, ໂລ​ຫະ​ທີ່ຫຸ້ມດ້ວຍ​ໂລ​ຫະມີຄ່າ ແລະ ເຄື່​ອງ​ທີ່​ເຮັດ​ດ້ວຍວັດ​ຖຸ​ດັ່ງ​ກ່າວ; ເຄື່ອງ​ເອ້ທຽມ; ເງິນ​ຫຼຽນ','Natural or cultured pearls, precious or semi-precious stones, precious metals, metals clad with precious metal, and articles thereof; imitation jewellery; coin',NULL,12899);
INSERT INTO `bm_customs_chapters` VALUES (96,14,'SUB-CHAPTER I','','NATURAL OR CULTURED PEARLS AND PRECIOUS OR SEMI-PRECIOUS STONES',NULL,12947);
INSERT INTO `bm_customs_chapters` VALUES (97,14,'SUB-CHAPTER II','','PRECIOUS METALS AND METALS CLAD WITH PRECIOUS METAL',NULL,12989);
INSERT INTO `bm_customs_chapters` VALUES (98,14,'SUB-CHAPTER III','','JEWELLERY, GOLDSMITHS’ AND SILVERSMITHS’ WARES AND OTHER ARTICLES',NULL,13048);
INSERT INTO `bm_customs_chapters` VALUES (99,15,'72','ເຫຼັກ ແລະ​ ເຫຼັກ​ກ້າ','Iron and steel',NULL,13170);
INSERT INTO `bm_customs_chapters` VALUES (100,15,'SUB-CHAPTER I','','PRIMARY MATERIALS; PRODUCTS IN GRANULAR OR POWDER FORM',NULL,13271);
INSERT INTO `bm_customs_chapters` VALUES (101,15,'SUB-CHAPTER II','','IRON AND NON-ALLOY STEEL',NULL,13323);
INSERT INTO `bm_customs_chapters` VALUES (102,20,'SUB-CHAPTER III','','STAINLESS STEEL',NULL,13751);
INSERT INTO `bm_customs_chapters` VALUES (103,20,'SUB-CHAPTER IV','','OTHER ALLOY STEEL; HOLLOW DRILL BARS AND RODS, of ALLOY OR NON-ALLOY STEEL',NULL,13816);
INSERT INTO `bm_customs_chapters` VALUES (104,20,'73','ເຄື່ອງຂອງ​ທີ່​ເຮັດດ້ວຍເຫຼັກ ຫຼື​ ເຫຼັກ​ກ້າ','Articles of iron or steel',NULL,13952);
INSERT INTO `bm_customs_chapters` VALUES (105,20,'74','ທອງແດງ ແລະ ​ເຄື່ອງ​ຂອງທີ່​ເຮັດ​ດ້ວຍ​ທອງແດງ','Copper and articles thereof',NULL,14441);
INSERT INTO `bm_customs_chapters` VALUES (106,20,'75','ນິ​ກເກິລ  ແລະ ​ເຄື່ອງ​ຂອງ​ທີ່​ເຮັດ​ດ້ວຍນິ​ກເກິລ','Nickel and articles thereof',NULL,14641);
INSERT INTO `bm_customs_chapters` VALUES (107,20,'76','ອາລຸຍ​ມິນຽມ ແລະ ​ເຄື່ອງຂອງທີ່​ເຮັດ​ດ້ວຍ​ອາ​ລູຍມິນຽມ','Aluminium and articles thereof',NULL,14738);
INSERT INTO `bm_customs_chapters` VALUES (108,20,'77','(ສະຫງວນໄວ້ໃຊ້ໃນອະນາຄົດໃນສາລະບາອັດຕາພາສີ)','(Reserved for possible future use in the Harmonized System)',NULL,14930);
INSERT INTO `bm_customs_chapters` VALUES (109,20,'78','ຊືນ ແລະ​ ເຄື່ອງຂອງ​ທີ່​ເຮັດ​ດ້ວຍຊືນ','Lead and articles thereof',NULL,14933);
INSERT INTO `bm_customs_chapters` VALUES (110,20,'79','ສັງ​ກະ​ສີ ແລະ​ ເຄື່ອງຂອງ​ທີ່ເຮັດ​ດ້ວຍສັງ​ກະ​ສີ','Zinc and articles thereof',NULL,15029);
INSERT INTO `bm_customs_chapters` VALUES (111,20,'80','ກົ່ວ ແລະ ຜະລິດຕະພັນຂອງສິ່ງດັ່ງກ່າວ','Tin and articles thereof',NULL,15124);
INSERT INTO `bm_customs_chapters` VALUES (112,20,'81','ໂລ​ຫະ​ທຳ​ມະ​ດາ​ຊະ​ນິດ​ອື່ນໆ; ໂລຫະຊະນິດເຊີ​​ເມັດ; ເຄື່ອງຂອງທີ່ເຮັດ​ດ້ວຍ​ວັດຖຸ​ດັ່ງ​ກ່າວ','Other base metals; cermets; articles thereof',NULL,15179);
INSERT INTO `bm_customs_chapters` VALUES (113,20,'82','ເຄື່ອງ​ມື​, ເຄື່ອງ​ໃຊ້, ເຄື່ອງຂອງ​ຊະ​ນິດ​ມີ​ຄົມ, ບ່ວງ ແລະ ສ້ອມທີ່​ເຮັດ​ດ້ວຍໂລ​ຫະ​ທຳ​ມະ​ດາ; ສິ້ນສ່ວນຂອງ​ເຄື່ອງ​ດັ່ງ​ກ່າວທີ່​ເຮັດ​ດ້ວຍ​ໂລ​ຫະ​ທຳ​ມະ​ດາ.','Tools, implements, cutlery, spoons and forks, of base metal; parts thereof of base metal',NULL,15301);
INSERT INTO `bm_customs_chapters` VALUES (114,20,'83','ເຄື່ອງ​ໃຊ້​ຕ່າງໆ ທີ່​ເຮັດ​ດ້ວຍ​ໂລ​ຫະ​ທຳ​ມະ​ດາ','Miscellaneous articles of base metal',NULL,15441);
INSERT INTO `bm_customs_chapters` VALUES (115,21,'84','ເຄື່ອງ​ປະ​ຕິ​ກອບນິວ​ເຄ​ລັຍ, ເຄື່ອງ​ຕົ້ົ້​ມ, ເຄື່ອງ​ຈັກ ແລະ ອຸປະກອນກົນຈັກ; ​ສ່ວນປະກອບຂອງເຄື່ອງ​ດັ່ງ​ກ່າວ','Nuclear reactors, boilers, machinery and mechanical appliances; parts thereof',NULL,15608);
INSERT INTO `bm_customs_chapters` VALUES (116,21,'85','ເຄື່ອງຈັກໄຟ​ຟ້າ ແລະ ເຄື່ອງ​ອຸ​ປະ​ກອນໄຟ​ຟ້າ ແລະ ສິ້ນສ່ວນ​ຂອງ​ເຄື່ອງ​ດັ່ງ​ກ່າວ; ເຄື່ອງບັນ​ທຶກສຽງ ແລະ​ ເຄື່ອງຖ່າຍ ທອດ​ສຽງ, ເຄື່ອງ​ບັນ​ທຶກ ແລະ ເຄື່ອງ​ຖ່າຍທອດ​ພາບ ແລະ ​ສຽງ​ທາງ​ໂທ​ລະພາບລວມທັງສິ້ນສ່ວນ ແລະ ​ສ່ວນ​ປະ​ກອບຂອງ​ເຄື່ອງ​ດັ່ງ​ກ່າວ.','Electrical machinery and equipment and parts thereof; sound recorders and reproducers, television image and sound recorders and reproducers, and parts and accessories of such articles',NULL,17870);
INSERT INTO `bm_customs_chapters` VALUES (117,22,'86','ຫົວຈັກ​ຂອງ​ລົດ​ໄຟ ຫຼື​ ລົດ​ລາງ, ລົດ​ທີ່​ແລ່ນເທິງ​ລາງ ແລະ ສ່ວນ​ປະ​ກອບ​ຂອງ​ເຄື່ອງ​ດັ່ງ​ກ່າວ; ເຄື່ອງ​ຕິດ​ຕັ້ງ​ຖາ​ວອນ ແລະ​  ອຸ​ປະ​ກອນຕິດ​ຕັ້ງ​ສຳ​ລັບ​ລາງ​ລົດ​ໄຟ ຫຼື​ ລາງ​ລົດ​ລາງ ແລະ​ ສ່ວນ​ປະ​ກອບ​ຂອງເຄື່ອງ​ດັ່ງ​ກ່າວ, ເຄື່ອງ​ອຸ​ປະ​ກອນ​ກົນຈັກ (ລວມ​ທັງເຄື່ອງ​ກົນຈັກ​ໄຟ​ຟ້າ) ສຳ​ລັບ​ໃຫ້​ສັນ​ຍານການ​ຈໍ​ລະ​ຈອນ​ທຸກ​ຊະ​ນິດ.','Railway or tramway locomotives, rolling-stock and parts thereof; railway or tramway track fixtures and fittings and parts thereof; mechanical (including electro-mechanical) traffic signalling equipment of all kinds',NULL,19309);
INSERT INTO `bm_customs_chapters` VALUES (118,22,'87','ຍານພາ​ຫະ​ນະທາງ​ບົກ ນອກ​ຈາກລົດທີ່​ແລ່ນເທິງ​ລາງ​ລົດ​ໄຟ ຫຼື​ ລາງ​ລົດ​ລາງ, ສິ້ນ​ສ່ວນ​ ແລະ ສ່ວນປະ​ກອບ​ຂອງຍານພາ​ຫະ​ນະ​ດັ່ງ​ກ່າວ.','Vehicles other than railway or tramway rolling-stock, and parts and accessories thereof',NULL,19376);
INSERT INTO `bm_customs_chapters` VALUES (119,22,'88','ພາ​ຫະ​ນະ​ທາງອາ​ກາດ, ຍານ​ອາ​ວະ​ກາດ ແລະ ​ສ່ວນ​ປະ​ກອບ​ຂອງ​ພາ​ຫະ​ນະດັ່ງ​ກ່າວ','Aircraft, spacecraft, and parts thereof',NULL,21692);
INSERT INTO `bm_customs_chapters` VALUES (120,22,'89','ກ່ຳ​ປັ່ນ, ເຮືອ ແລະ​ ສິ່ງ​ກໍ່​ສ້າງທີ່​ຟູ​ເທິງ​ໜ້ານໍ້າ','Ships, boats and floating structures',NULL,21769);
INSERT INTO `bm_customs_chapters` VALUES (121,23,'90','ເຄື່ອງມື ແລະ ອຸ​ປະ​ກອນ​ທີ່​ໃຊ້​ໃນ​ທາງທັດ​ສະ​ນະ​ສາດ, ການຖ່າຍ​ຮູບ, ການ​ສ້າງຮູບ​ເງົາ, ການ​ວັດ​ແທກ, ​ການກວດ​ສອບ, ​ການ​ວັດແຫກຄວາມຊັດ ເຈນ, ​ການແ​ພດ​ ຫຼື​ ສັນ​ຍາກໍາ; ສິ້ນ​ສ່ວນ ແລະ ສ່ວນ​ປະ​ກອບ​ຂອງ​ສິ່ງ​ດັ່ງ​ກ່າວ.','Optical, photographic, cinematographic, measuring, checking, precision, medical or surgical instruments and apparatus; parts and accessories thereof',NULL,21895);
INSERT INTO `bm_customs_chapters` VALUES (122,23,'91','ໂມງ​ຊະ​ນິດ​ຕັ້ງ ຫຼື ແຂວນຝາ ແລະ ໂມງໃສ່ແຂນ  ແລະ ສິ້ນ​ສ່ວນ​ຂອງ​ສິ່ງ​ດັ່ງ​ກ່າວ','Clocks and watches and parts thereof',NULL,22360);
INSERT INTO `bm_customs_chapters` VALUES (123,23,'92','ເຄື່ອງດົນຕີ; ສິ້ນສ່ວນ ແລະ ສ່ວນປະກອບຂອງເຄື່ອງດັ່ງ​ກ່າວ','Musical instruments; parts and accessories of such articles',NULL,22511);
INSERT INTO `bm_customs_chapters` VALUES (124,24,'93','ອາ​ວຸດ ແລະ ​ລູກ​ປືນ; ລວມທັງສ່ວນປະກອບ ແລະ​ ອຸປະກອນປະກອບ​ຂອງ​ສິ່ງ​ດັ່ງ​ກ່າວ','Arms and ammunition; parts and accessories thereof',NULL,22582);
INSERT INTO `bm_customs_chapters` VALUES (125,25,'94','ເຄື່ອງ​ເຟີ​ນິ​ເຈີ​; ​ຕຽງ, ເສື່ອ, ຖານ​ຮອງ​ເສື່ອ, ເບາະ ​ສິ່ງຈັດ​ແຕ່ງ​ຍັດ​ໃສ້​ທີ່​ຄ້າຍ​ຄືກັ​ນ; ໂຄມໄຟ ແລະ ເຄື່ອງ​ອຸ​ປະ​ກອນ​ໃຫ້​ແສງ​ສະ​ຫວ່າງ​, ທີ່​ບໍ່​ໄດ້​ລະ​ບຸ ຫຼື​ ລວມໄວ້​ໃນ​ບ່ອນອື່ນໆ; ປ້າຍສະທ້ອນແສງ; ແຜ່ນປ້າຍສະທ້ອນແສງ​ ແລະ ເຄື່ອງ​ຂອງທີ່​ຄ້າຍ​ຄຽງ; ສິ່ງກໍ່ສ້າງສຳເລັດຮູບຂອງອາຄານທີ່ບໍ່ທັນປະກອບ','Furniture; bedding, mattresses, mattress supports, cushions and similar stuffed furnishings; lamps and lighting fittings, not elsewhere specified or included; illuminated signs, illuminated name-plates and the like; prefabricated buildings',NULL,22655);
INSERT INTO `bm_customs_chapters` VALUES (126,25,'95','ເຄື່ອງ​ຫຼິ້ນ​, ເຄື່ອງຫຼິ້ນເກມ ແລະ​ ເຄື່ອງ​ໃຊ້​ທີ່​ຈໍາເປັນ​ໃນ​ການ​ຫຼິ້ນ​ກິ​ລາ; ສິ້ນສ່ວນ ແລະ ສ່ວນ​ປະ​ກອບຂອງເຄື່ອງດັ່ງ​ກ່າວ','Toys, games and sports requisites; parts and accessories thereof',NULL,22881);
INSERT INTO `bm_customs_chapters` VALUES (127,25,'96','ຜະ​ລິດ​ຕະ​ພັນ​​ຕ່າງໆ','Miscellaneous manufactured articles',NULL,23046);
INSERT INTO `bm_customs_chapters` VALUES (128,26,'97','ເຄື່ອງສິນລະ​ປະກຳ, ເຄື່ອງ​ນັກສະສົມລວບລວມ ແລະ ​ເຄື່ອງວັດ​ຖຸ​ບູ​ຮານ','Works of art, collectors’ pieces and antiques',NULL,23264);
