INSERT INTO `bm_customs_tariff` VALUES (302,'0303.31.00','00','- - Halibut (Reinhardtius hippoglossoides, Hippoglossus hippoglossus, Hippoglossus stenolepis)','- - ປາລິ້ນໝາຈຳພວກຈັກຜານ (ເຣນຮາດຊຽສ ຮິບໂປກລອສຊອຍເດສ, ຮິບໂປ ໂກລສ໌ຊັສ ຮິບໂປໂກລສ໌ຊັສ, ຮິບໂປໂກລສ໌ຊັສ ສະຕິໂນເລພິສ໌)','ກລ','10','10','0','0','0','0','0','0','0','0',3,0,1,417);
INSERT INTO `bm_customs_tariff` VALUES (303,'0303.32.00','00','- - Plaice (Pleuronectes platessa)','- - ປາເພລຊ໌ (ພລູໂຣເນກເທສ ພລາເທສຊາ)','ກລ','10','10','0','0','0','0','0','0','0','0',3,0,1,418);
INSERT INTO `bm_customs_tariff` VALUES (304,'0303.33.00','00','- - Sole (Solea spp.)','- - ປາໂຊລ (ຊະນິດໂຊເລຍ)','ກລ','10','10','0','0','0','0','0','0','0','0',3,0,1,419);
