INSERT INTO `bm_customs_tariff` VALUES (334,'0303.66.00','00','- - Hake (Merluccius spp., Urophycis spp.)','-​​ -​​ ປາ​ເຮກ (ຊະ​ນິດ​ເມິ​ລັກ​ຊຽ​ສ, ຊະ​ນິດ​ຍູ​ໂຣ​ໄຟ​ຊິ​ສ.)','ກລ','10','10','0','0','0','0','0','0','0','0',3,0,1,453);
INSERT INTO `bm_customs_tariff` VALUES (335,'0303.67.00','00','- - Alaska Pollack (Theragra chalcogramma)','- - ປາອະລາສກາ ພອລລັກ (ເທຣາກາ ຊາລໂຄແກຣມມາ)','ກລ','10','10','0','0','0','0','0','0','0','0',3,0,1,454);
INSERT INTO `bm_customs_tariff` VALUES (336,'0303.68.00','00','- - Blue whitings (Micromesistius poutassou, Micromesistius australis)','- - ປາບລູໄວທິງ (ໄມໂຄຣມີຊິສທິອັສ ພໍທັສຊົວ, ໄມໂຄຣມີຊິສທິອັສ ອົສຕຣາລິສ)','ກລ','10','10','0','0','0','0','0','0','0','0',3,0,1,455);
