INSERT INTO `bm_customs_tariff` VALUES (354,'0303.89.22','00','- - - - Swamp barb (Puntius chola)','- - - - ປາຊະວຳບາຣ໌ບ (ພັນຊຽດສ໌ ໂຈລາ)','ກລ','10','10','0','0','0','0','0','0','0','0',3,0,1,473);
INSERT INTO `bm_customs_tariff` VALUES (355,'0303.89.26','00','- - - - Indian threadfins (Polynemus indicus) and silver grunts (Pomadasys argenteus)','- - - - ປາອິນດຽນແທຣດຟິນ (ພໍລິນີມັສ ອິນດິຄັສ) ແລະ ປາຊິລເວີຣ໌ກຣັນທ໌ (ໂພມາດາຊີ ອາຣ໌ເຈນທິອັສ)','ກລ','10','10','0','0','0','0','0','0','0','0',3,0,1,474);
INSERT INTO `bm_customs_tariff` VALUES (356,'0303.89.27','00','- - - - Hilsa shad (Tenualosa ilisha)','- - - - ປາຕະລຸມພຸກ (ທີນົວໂລຊາ ອິລິຊາ)','ກລ','10','10','0','0','0','0','0','0','0','0',3,0,1,475);
INSERT INTO `bm_customs_tariff` VALUES (357,'0303.89.28','00','- - - - Wallago (Wallago attu) and giant river-catfish (Sperata seenghala)','- - - - ປາຄ້າວ (ວັລລາໂກ ອັດທູ) ແລະ ປາກົດຫົວສຽມ (ສະປິຣາທາຊີງາລາ)','ກລ','20','20','0','0','0','0','0','0','0','0',3,0,1,476);
